<template>
  <div class="input-container">
    <h2>📝 Input Data Anak</h2>
    <p>Masukkan data anak untuk pemantauan stunting</p>

    <form @submit.prevent="submitForm" class="form">
      <div class="form-row">
        <div class="form-group">
          <label>Nama Anak *</label>
          <input v-model="form.nama" type="text" required />
        </div>
        <div class="form-group">
          <label>Jenis Kelamin *</label>
          <select v-model="form.jenisKelamin" required>
            <option value="">Pilih...</option>
            <option value="Laki-laki">Laki-laki</option>
            <option value="Perempuan">Perempuan</option>
          </select>
        </div>
      </div>

      <div class="form-row">
        <div class="form-group">
          <label>Berat Badan (kg) *</label>
          <input
            v-model.number="form.beratBadan"
            type="number"
            step="0.1"
            required
          />
        </div>
        <div class="form-group">
          <label>Tinggi Badan (cm) *</label>
          <input
            v-model.number="form.tinggiBadan"
            type="number"
            step="0.1"
            required
          />
        </div>
      </div>

      <div class="form-row">
        <div class="form-group full">
          <label>Catatan</label>
          <textarea v-model="form.catatan"></textarea>
        </div>
      </div>

      <div class="form-actions">
        <button type="button" @click="resetForm" class="btn-reset">
          Reset
        </button>
        <button type="submit" :disabled="!isFormValid" class="btn-save">
          Simpan Data
        </button>
      </div>
    </form>

    <div v-if="successMessage" class="success">{{ successMessage }}</div>
  </div>
</template>

<script>
export default {
  name: "InputAnak",
  data() {
    return {
      form: {
        nama: "",
        jenisKelamin: "",
        beratBadan: null,
        tinggiBadan: null,
        catatan: "",
      },
      successMessage: "",
    };
  },
  computed: {
    isFormValid() {
      return (
        this.form.nama &&
        this.form.jenisKelamin &&
        this.form.beratBadan > 0 &&
        this.form.tinggiBadan > 0
      );
    },
  },
  methods: {
    submitForm() {
      const data = {
        ...this.form,
        id: Date.now(),
        date: new Date().toLocaleDateString(),
      };

      const existing = JSON.parse(localStorage.getItem("anakData") || "[]");
      existing.push(data);
      localStorage.setItem("anakData", JSON.stringify(existing));

      this.successMessage = `✅ Data ${this.form.nama} disimpan!`;
      this.resetForm();

      setTimeout(() => {
        this.successMessage = "";
      }, 3000);
    },
    resetForm() {
      this.form = {
        nama: "",
        jenisKelamin: "",
        beratBadan: null,
        tinggiBadan: null,
        catatan: "",
      };
    },
  },
};
</script>

