<template>
  <section class="gizi-section">
    <div class="card">
      <header class="header">
        <h2>🧮 Kalkulator Status Gizi</h2>
        <p>
          Hitung status gizi anak berdasarkan BB/U dan TB/U secara sederhana.
        </p>
      </header>

      <div class="form">
        <div class="input-group">
          <label>Umur Anak (bulan)</label>
          <input type="number" v-model.number="umur" placeholder="Contoh: 24" />
        </div>

        <div class="input-group">
          <label>Berat Badan (kg)</label>
          <input
            type="number"
            v-model.number="berat"
            placeholder="Contoh: 12"
          />
        </div>

        <div class="input-group">
          <label>Tinggi Badan (cm)</label>
          <input
            type="number"
            v-model.number="tinggi"
            placeholder="Contoh: 85"
          />
        </div>

        <!-- Tombol -->
        <div class="btn-group">
          <button class="btn primary" @click="hitungGizi">
            Hitung Status Gizi
          </button>
          <button class="btn reset" @click="resetForm">Reset</button>
        </div>
      </div>

      <div v-if="hasil" class="result">
        <h3>📊 Hasil Perhitungan</h3>
        <p><strong>BB/U:</strong> {{ hasil.bbu }}</p>
        <p><strong>TB/U:</strong> {{ hasil.tbu }}</p>
      </div>
    </div>
  </section>
</template>

<script>
export default {
  name: "KalkulatorGizi",
  data() {
    return {
      umur: null,
      berat: null,
      tinggi: null,
      hasil: null,
    };
  },
  methods: {
    hitungGizi() {
      if (!this.umur || !this.berat || !this.tinggi) {
        alert("Mohon isi semua data terlebih dahulu");
        return;
      }

      let bbu = "";
      let tbu = "";

      // BB/U (pendekatan sederhana)
      if (this.berat < this.umur * 0.25) {
        bbu = "Gizi Buruk";
      } else if (this.berat < this.umur * 0.3) {
        bbu = "Gizi Kurang";
      } else if (this.berat <= this.umur * 0.45) {
        bbu = "Gizi Normal";
      } else {
        bbu = "Gizi Lebih";
      }

      // TB/U (pendekatan sederhana)
      if (this.tinggi < this.umur * 2.5) {
        tbu = "Sangat Pendek";
      } else if (this.tinggi < this.umur * 3) {
        tbu = "Pendek (Stunting)";
      } else {
        tbu = "Normal";
      }

      this.hasil = { bbu, tbu };
    },

    resetForm() {
      this.umur = null;
      this.berat = null;
      this.tinggi = null;
      this.hasil = null;
    },
  },
};
</script>

